BEGIN;
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('9b000000-0000-4000-8000-000000000001','learning-host@example.invalid',now()),('9b000000-0000-4000-8000-000000000002','learning-buyer@example.invalid',now()),('9b000000-0000-4000-8000-000000000003','learning-other@example.invalid',now());
INSERT INTO auth.sessions(id,user_id) SELECT id,id FROM auth.users WHERE id::text LIKE '9b000000-%';
INSERT INTO public.institutions(id,slug,name) VALUES('9b000000-0000-4000-8000-000000000010','fixture-paid-learning','Synthetic learning campus');
INSERT INTO public.departments(id,institution_id,slug,name) VALUES('9b000000-0000-4000-8000-000000000011','9b000000-0000-4000-8000-000000000010','science','Science');
INSERT INTO public.courses(id,institution_id,department_id,code,title) VALUES('9b000000-0000-4000-8000-000000000012','9b000000-0000-4000-8000-000000000010','9b000000-0000-4000-8000-000000000011','LEARN1','Learning');
INSERT INTO public.student_profiles(user_id,institution_id,display_name,verified_at) SELECT id,'9b000000-0000-4000-8000-000000000010','Synthetic learner',now() FROM auth.users WHERE id::text LIKE '9b000000-%';
INSERT INTO public.interactive_classes(id,institution_id,course_id,host_id,title,starts_at,ends_at,capacity,price_kobo,status,provider_ready,room_name,creation_key) VALUES('9b000000-0000-4000-8000-000000000013','9b000000-0000-4000-8000-000000000010','9b000000-0000-4000-8000-000000000012','9b000000-0000-4000-8000-000000000001','Synthetic paid class',now()+interval '5 minutes',now()+interval '2 hours',2,20000,'room_open',true,'wk-class-9b000000-0000-4000-8000-000000000013','fixture-paid-learning-key');
INSERT INTO public.personal_learning_requests(id,institution_id,student_id,creator_id,kind,description,budget_kobo,quote_kobo,state,creation_key) VALUES('9b000000-0000-4000-8000-000000000014','9b000000-0000-4000-8000-000000000010','9b000000-0000-4000-8000-000000000002','9b000000-0000-4000-8000-000000000001','tutoring','Synthetic tutorial request for a regression test',30000,30000,'quoted','fixture-paid-service-key');
DO $$ BEGIN
 IF public.reserve_live_learning_checkout('9b000000-0000-4000-8000-000000000002','class','9b000000-0000-4000-8000-000000000013','fixture-class-payment-key','fixture-v1') IS NOT NULL THEN RAISE EXCEPTION 'Unapproved paid learning checkout allowed'; END IF;
 IF has_function_privilege('authenticated','public.settle_live_learning_charge(text,uuid,bigint,bigint)','EXECUTE') OR has_table_privilege('service_role','live_finance.learning_receipts','INSERT') THEN RAISE EXCEPTION 'Unsafe payment privileges'; END IF;
END $$;
-- Test-only terms in this rollback transaction. Not founder-approved commercial values.
UPDATE live_finance.runtime_gate SET allow_checkout=true,terms_version='fixture-v1',refund_policy_version='fixture-refunds',platform_fee_bps=1000,fee_bearer='platform',license_seconds=3600,approved_at=now() WHERE singleton;
UPDATE live_finance.learning_gate SET allow_checkout=true,terms_version='fixture-v1',approved_at=now() WHERE singleton;
DO $$ DECLARE b uuid:='9b000000-0000-4000-8000-000000000002'; h uuid:='9b000000-0000-4000-8000-000000000001'; c uuid:='9b000000-0000-4000-8000-000000000013'; s uuid:='9b000000-0000-4000-8000-000000000014'; o jsonb; ref text; e jsonb; id uuid; rv text;
BEGIN
 o:=public.reserve_live_learning_checkout(b,'class',c,'fixture-class-payment-key','fixture-v1');ref:=o->>'reference';id:=(o->>'orderId')::uuid;
 IF o->>'create' IS DISTINCT FROM 'true' OR ref !~ '^ll_[0-9a-f]{32}$' OR (o->>'amountKobo')::bigint<>20000 THEN RAISE EXCEPTION 'Invalid trusted order snapshot'; END IF;
 IF public.reserve_live_learning_checkout(b,'class',c,'fixture-class-payment-key','fixture-v1')->>'create'<>'false' THEN RAISE EXCEPTION 'Checkout replay'; END IF;
 IF public.reserve_live_learning_checkout('9b000000-0000-4000-8000-000000000003','class',c,'fixture-class-other-key','fixture-v1') IS NOT NULL THEN RAISE EXCEPTION 'Reserved seat exceeded capacity'; END IF;
 IF public.authorized_hosted_class_room(b,c) IS NOT NULL THEN RAISE EXCEPTION 'Unpaid class entry'; END IF;
 IF NOT public.finish_live_learning_checkout(id,'https://checkout.paystack.com/fixture') THEN RAISE EXCEPTION 'Checkout finish failed'; END IF;
 IF NOT public.live_learning_can_return(b,ref,'fixture-v1') THEN RAISE EXCEPTION 'Checkout return failed'; END IF;
 IF public.record_live_learning_charge(ref,'9600012345',repeat('a',64))<>'accepted' THEN RAISE EXCEPTION 'Inbox insert'; END IF;
 IF public.record_live_learning_charge(ref,'9600012345',repeat('a',64))<>'duplicate' THEN RAISE EXCEPTION 'Inbox replay'; END IF;
 e:=public.claim_live_learning_charge();
 IF public.claim_live_learning_charge() IS NOT NULL THEN RAISE EXCEPTION 'Concurrent lease'; END IF;
 IF public.settle_live_learning_charge('9600012345',gen_random_uuid(),20000,100) OR public.settle_live_learning_charge('9600012345',(e->>'leaseId')::uuid,20001,100) THEN RAISE EXCEPTION 'Incorrect payment settled'; END IF;
 IF NOT public.settle_live_learning_charge('9600012345',(e->>'leaseId')::uuid,20000,100) THEN RAISE EXCEPTION 'Verified charge not settled'; END IF;
 IF public.authorized_hosted_class_room(b,c)->>'role' IS DISTINCT FROM 'participant' THEN RAISE EXCEPTION 'Paid enrollment missing'; END IF;
 IF (SELECT amount_kobo FROM live_finance.learning_journal WHERE transaction_id='9600012345' AND kind='platform')<>2000 OR (SELECT amount_kobo FROM live_finance.learning_journal WHERE transaction_id='9600012345' AND kind='creator')<>18000 THEN RAISE EXCEPTION 'Commission snapshot wrong'; END IF;
 IF public.record_live_learning_charge(ref,'9600012346',repeat('b',64))<>'accepted' THEN RAISE EXCEPTION 'Duplicate charge not durably recorded'; END IF;
 e:=public.claim_live_learning_charge();IF NOT public.settle_live_learning_charge('9600012346',(e->>'leaseId')::uuid,20000,100) THEN RAISE EXCEPTION 'Duplicate settlement failed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM live_finance.learning_receipts WHERE transaction_id='9600012346' AND duplicate AND NOT delivered) THEN RAISE EXCEPTION 'Duplicate allocated twice'; END IF;
 IF public.enqueue_live_reversal_event('refund.processed','9600012347',repeat('c',64))<>'accepted' THEN RAISE EXCEPTION 'Refund event rejected'; END IF;
 e:=public.claim_live_reversal_event();
 IF NOT public.apply_live_refund_event('9600012347',(e->>'lease')::uuid,'9600012346',20000) THEN RAISE EXCEPTION 'Duplicate refund failed'; END IF;
 IF public.authorized_hosted_class_room(b,c) IS NULL THEN RAISE EXCEPTION 'Duplicate refund revoked primary access'; END IF;
 rv:=ref||':'||repeat('d',64);
 IF public.enqueue_live_reversal_event('refund.processed',rv,repeat('d',64))<>'accepted' THEN RAISE EXCEPTION 'Reference refund rejected'; END IF;
 e:=public.claim_live_reversal_event();
 IF public.apply_live_refund_event(rv,(e->>'lease')::uuid,'9600012345',19999) OR NOT public.apply_live_refund_event(rv,(e->>'lease')::uuid,'9600012345',20000) THEN RAISE EXCEPTION 'Full refund verification failed'; END IF;
 IF public.authorized_hosted_class_room(b,c) IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.learning_participant_removals WHERE class_id=c AND student_id=b) THEN RAISE EXCEPTION 'Refund access revocation failed'; END IF;
 o:=public.reserve_live_learning_checkout(b,'service',s,'fixture-service-payment-key','fixture-v1');ref:=o->>'reference';
 IF ref IS NULL THEN RAISE EXCEPTION 'Service reservation failed'; END IF;
 IF public.record_live_learning_charge(ref,'9600012348',repeat('e',64))<>'accepted' THEN RAISE EXCEPTION 'Service charge enqueue failed'; END IF;
 e:=public.claim_live_learning_charge();
 IF NOT public.settle_live_learning_charge('9600012348',(e->>'leaseId')::uuid,30000,200) THEN RAISE EXCEPTION 'Verified tutoring settlement failed'; END IF;
 IF (SELECT req.state FROM public.personal_learning_requests req WHERE req.id=s) IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'Tutoring not accepted'; END IF;
END $$;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','9b000000-0000-4000-8000-000000000001',true),set_config('request.jwt.claims','{"sub":"9b000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"9b000000-0000-4000-8000-000000000001"}',true);
SELECT public.hosted_learning_action('start_help','{"requestId":"9b000000-0000-4000-8000-000000000014"}');
RESET ROLE;
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('9b000000-0000-4000-8000-000000000004','reviewer@example.invalid',now()),('9b000000-0000-4000-8000-000000000005','finance-reviewer@example.invalid',now());
INSERT INTO public.platform_staff(user_id,role,active) VALUES('9b000000-0000-4000-8000-000000000004','moderator',true),('9b000000-0000-4000-8000-000000000005','admin',true);
INSERT INTO public.governance_staff_role_grants(user_id,role) VALUES('9b000000-0000-4000-8000-000000000004','content_moderator'),('9b000000-0000-4000-8000-000000000005','finance_reviewer');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','9b000000-0000-4000-8000-000000000002',true),set_config('request.jwt.claims','{"sub":"9b000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"9b000000-0000-4000-8000-000000000002"}',true);
SELECT public.hosted_learning_action('dispute_help','{"requestId":"9b000000-0000-4000-8000-000000000014","reason":"Synthetic disputed tutoring session"}');
RESET ROLE;
DO $$ DECLARE m uuid:='9b000000-0000-4000-8000-000000000004'; f uuid:='9b000000-0000-4000-8000-000000000005'; s uuid:='9b000000-0000-4000-8000-000000000014'; d uuid; review uuid; e jsonb;
BEGIN
 SELECT id INTO d FROM public.personal_learning_disputes WHERE request_id=s;
 IF jsonb_array_length(public.week7_learning_review_queue(m,'disputes',10)->'items')<>1 THEN RAISE EXCEPTION 'Dispute queue failed'; END IF;
 BEGIN PERFORM public.week7_learning_review_queue(f,'disputes',10); RAISE EXCEPTION 'Finance read dispute'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.week7_resolve_learning_dispute(f,d,'cancel_service','Unauthorized scope attempt'); RAISE EXCEPTION 'Finance cancelled dispute'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 PERFORM public.week7_resolve_learning_dispute(m,d,'cancel_service','Synthetic dispute cancellation');
 SELECT id INTO review FROM public.learning_refund_reviews WHERE resource_id=s;
 IF review IS NULL THEN RAISE EXCEPTION 'Refund review missing'; END IF;
 BEGIN PERFORM public.week7_record_learning_refund_review(f,review,'Synthetic unverified refund'); RAISE EXCEPTION 'Unverified refund marked recorded'; EXCEPTION WHEN unique_violation THEN NULL; END;
 BEGIN PERFORM public.week7_learning_review_queue(m,'refunds',10); RAISE EXCEPTION 'Moderator read finance'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 PERFORM public.enqueue_live_reversal_event('refund.processed','9600012349',repeat('f',64));
 e:=public.claim_live_reversal_event();
 IF NOT public.apply_live_refund_event('9600012349',(e->>'lease')::uuid,'9600012348',30000) THEN RAISE EXCEPTION 'Verified service reversal failed'; END IF;
 PERFORM public.week7_record_learning_refund_review(f,review,'Synthetic provider refund verified');
 IF (SELECT state FROM public.learning_refund_reviews WHERE id=review)<>'recorded' THEN RAISE EXCEPTION 'Review not recorded'; END IF;
 IF has_function_privilege('authenticated','public.week7_record_learning_refund_review(uuid,uuid,text)','EXECUTE') THEN RAISE EXCEPTION 'Browser has refund review RPC'; END IF;
END $$;
ROLLBACK;
